import type { DatabaseSync } from 'node:sqlite';
import type { LlmProvider } from './provider';
import { QUERY_SYSTEM } from './prompts';
import { QueryArgError, QueryExecutor, type QueryResult } from './query-tools';

export type AskResult =
  | ({ ok: true } & QueryResult)
  | { ok: false; answer: string; tool: string | null };

/**
 * Natural-language questions -> one typed, read-only query tool.
 * The answer text is produced by deterministic code from the query result, so
 * numbers shown to the user are never generated by the model.
 */
export async function askQuestion(
  provider: LlmProvider,
  db: DatabaseSync,
  userId: string,
  question: string,
  today: string,
  currency = 'INR'
): Promise<AskResult> {
  const trimmed = question.trim().slice(0, 500);
  if (!trimmed) return { ok: false, answer: 'Ask a question about your spending, income or balances.', tool: null };

  const executor = new QueryExecutor(db, userId, today, currency);
  const choice = await provider.chooseTool({
    task: 'query',
    system: QUERY_SYSTEM,
    question: `Today is ${today}.\n\n${trimmed}`,
    tools: executor.toolDefinitions(),
  });

  const call = choice.data;
  if (!call) {
    return { ok: false, answer: "I can only answer questions about your spending, income and balances, and that one didn't map to a query I support.", tool: null };
  }
  try {
    return { ok: true, ...executor.execute(call.name, call.input) };
  } catch (err) {
    if (err instanceof QueryArgError) {
      return { ok: false, answer: `I couldn't run that query safely (${err.message}). Try rephrasing.`, tool: call.name };
    }
    throw err;
  }
}
